          id: "cloudflare",
          name: "Cloudflare",
          status: ok(health.services.cloudflare) ? "healthy" : "unhealthy",
          message: ok(health.services.cloudflare)
            ? "Gateway & R2 OK"
            : "CS csatlakozási hiba",
        },
      ];

      setServices(newServices);
      setLastCheck(new Date().toLocaleString("hu-HU"));
    } catch (error: any) {
      console.error("Health check error:", error);
      setServices((prev) =>
        prev.map((s) => ({
          ...s,
          status: "unhealthy",
          message: "Szerver nem elérhető",
        })),
      );
    } finally {
      setIsChecking(false);
    }
  };

  const handleToggle = async (serviceId: string, currentlyHealthy: boolean) => {
    if (serviceId === "agents" || serviceId === "mcp") {
      toast.info(`${serviceId} állapotát a rendszer automatikusan kezeli`);
      return;
    }

    setLoading((prev) => ({ ...prev, [serviceId]: true }));
    try {
      if (currentlyHealthy) {
        if (serviceId === "anythingllm") {
          toast.info("AnythingLLM Desktop app – manuálisan zárd be");
          return;
        }
        const result = await api.stopService(serviceId as any);
        if (result.success) toast.success(result.message);
        else toast.error(result.message);
      } else {
        const result = await api.startService(serviceId as any);
        if (result.success) toast.success(result.message);
        else toast.error(result.message);
      }
      await checkHealth();
    } catch (e: any) {
      toast.error(e.message || "Művelet sikertelen");
    } finally {
      setLoading((prev) => ({ ...prev, [serviceId]: false }));
    }
  };

  useEffect(() => {
    checkHealth();
    const interval = setInterval(checkHealth, 30000); // 30s as per masterplan V3
    return () => clearInterval(interval);
  }, []);

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "healthy":
        return (
          <CheckCircle size={20} className="text-green-500" weight="fill" />
        );
      case "unhealthy":
        return <XCircle size={14} className="text-red-500" weight="fill" />;
      case "checking":
        return (
          <Circle
            size={14}
            className="text-yellow-500 animate-pulse"
            weight="fill"
          />
        );
      default:
        return <Warning size={14} className="text-gray-500" />;
    }
  };

  const healthyCount = services.filter((s) => s.status === "healthy").length;
  const totalCount = services.length;

  return (
    <Card className="glass-card border-white/10">
      <CardHeader className="flex flex-row items-center justify-between pb-2 border-b border-white/5">
        <CardTitle className="text-sm font-space font-bold tracking-tight uppercase text-muted-foreground flex items-center gap-2">
          <ArrowsClockwise
            size={16}
            className={isChecking ? "animate-spin" : ""}
          />
          System Engine Health
        </CardTitle>
        <div className="flex items-center gap-2">
          <Badge
            variant={healthyCount === totalCount ? "default" : "destructive"}
            className="text-[10px]"
          >
            {healthyCount}/{totalCount} OK
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="p-0">
        <div className="divide-y divide-white/5">
          {services.map((service) => {
            const isHealthy = service.status === "healthy";
            const canToggle =
              service.id === "ollama" ||
              service.id === "anythingllm" ||
              service.id === "python";

            return (
              <div
                key={service.id}
                className="flex items-center justify-between p-3 hover:bg-white/5 transition-colors"
              >
                <div className="flex items-center gap-3">
                  {getStatusIcon(service.status)}
                  <div>
                    <p className="font-medium text-xs font-mono">
                      {service.name}
                    </p>
                    <p className="text-[10px] text-muted-foreground truncate max-w-[120px]">
                      {service.message || "System online"}
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  {canToggle && (
                    <Switch
                      checked={isHealthy}
                      disabled={loading[service.id] || isChecking}
                      onCheckedChange={() =>
                        handleToggle(service.id, isHealthy)
                      }
                      className="scale-75"
                    />
                  )}
                  {!canToggle && (
                    <Badge
                      variant="outline"
                      className="text-[9px] h-5 opacity-50"
                    >
                      AUTO
                    </Badge>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        <div className="p-3 bg-muted/20 border-t border-white/5">
          <p className="text-[9px] text-muted-foreground font-mono uppercase text-center">
            Last Check: {lastCheck || "Initializing..."}
          </p>
        </div>
      </CardContent>
    </Card>
  );
}

import { Router } from "express";
import { agentManager } from "../../agents/AgentManager.js";
import { mcpProcessManager } from "../McpProcessManager.js";
import {
  checkOllamaHealth,
  checkAnythingLLMHealth,
  checkPythonHealth,
  checkCloudflareHealth,
  buildHealthResponse,
} from "../../utils/health.js";
import { AppError } from "../../utils/AppError.js";
import { asyncHandler } from "../middleware/errorHandler.js";

export function createHealthRoutes(): Router {
  const router = Router();

  /**
   * @swagger
   * /api/health:
   *   get:
   *     summary: System Health Check
   *     description: Checks the status of internal components, Ollama, and AnythingLLM.
   *     responses:
   *       200:
   *         description: Health status object
   */
  router.get(
    "/",
    asyncHandler(async (req, res) => {
      const [ollama, anythingllm, python, cloudflare] = await Promise.all([
        checkOllamaHealth(),
        checkAnythingLLMHealth(),
        checkPythonHealth(),
        checkCloudflareHealth(),
      ]);
      const agentsCount = agentManager.listAgents().length;
      const mcpCount = mcpProcessManager.getServersStatus().length;
      const payload = buildHealthResponse(
        ollama,
        anythingllm,
        python,
        cloudflare,
        agentsCount,
        mcpCount,
        (req as unknown as Record<string, unknown>).id as string,
      );
      res.json(payload);
    }),
  );

  return router;
}

/**
 * systemHealth.ts - Service Health Check Utility
 *
 * Part of ProjectConductor 2.0 "Chief-of-Staff" upgrade.
 * Monitors all system services and provides unified health status.
 *
 * @module utils/systemHealth
 */

import { config } from '../config/index.js';
import { logInfo, logError } from './logger.js';

const SOURCE = 'systemHealth';

// ============================================================================
// Types
// ============================================================================

export type ServiceStatus = 'healthy' | 'degraded' | 'unhealthy' | 'unknown';

export interface ServiceHealth {
    name: string;
    status: ServiceStatus;
    latencyMs?: number;
    lastCheck: Date;
    error?: string;
    details?: Record<string, unknown>;
}

export interface SystemHealthReport {
    timestamp: Date;
    overallStatus: ServiceStatus;
    services: ServiceHealth[];
    summary: {
        healthy: number;
        degraded: number;
        unhealthy: number;
        unknown: number;
    };
}

export interface HealthCheckConfig {
    timeoutMs?: number;
    services?: string[];
}

// ============================================================================
// Service Definitions
// ============================================================================

interface ServiceDefinition {
    name: string;
    check: () => Promise<ServiceHealth>;
}

const SERVICES: ServiceDefinition[] = [];

/**
 * Register a service for health monitoring
 */
export function registerService(definition: ServiceDefinition): void {
    SERVICES.push(definition);
    logInfo(SOURCE, `Registered service: ${definition.name}`);
}

// ============================================================================
// Built-in Health Checks
// ============================================================================

/**
 * Check Ollama LLM service
 */
async function checkOllama(timeoutMs: number): Promise<ServiceHealth> {
    const name = 'Ollama';
    const start = Date.now();
    const baseUrl = process.env.OLLAMA_BASE_URL || 'http://localhost:11434';

    try {
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), timeoutMs);

        const response = await fetch(`${baseUrl}/api/tags`, {
            signal: controller.signal
        });
        clearTimeout(timeout);

        const latencyMs = Date.now() - start;

        if (response.ok) {
            const data = await response.json() as { models?: unknown[] };
            return {
                name,
                status: 'healthy',
                latencyMs,
                lastCheck: new Date(),
                details: {
                    url: baseUrl,
                    modelsLoaded: data.models?.length || 0
                }
            };
        }

        return {
            name,
            status: 'degraded',
            latencyMs,
            lastCheck: new Date(),
            error: `HTTP ${response.status}`
        };
    } catch (error) {
        return {
            name,
            status: 'unhealthy',
            lastCheck: new Date(),
            error: error instanceof Error ? error.message : 'Connection failed'
        };
    }
}

