// Main API
// ============================================================================

/**
 * Run health checks on all registered services
 */
export async function checkAllServices(
    options: HealthCheckConfig = {}
): Promise<SystemHealthReport> {
    const timeoutMs = options.timeoutMs || 5000;
    logInfo(SOURCE, 'Starting health check for all services...');

    const startTime = Date.now();

    // Built-in checks
    const builtInChecks: Promise<ServiceHealth>[] = [
        checkNodeProcess(),
        checkOllama(timeoutMs),
        checkPythonAPI(timeoutMs),
        checkMCPServer(timeoutMs),
        checkAnythingLLM(timeoutMs),
        checkDashboard(timeoutMs)
    ];

    // Add registered services
    const customChecks = SERVICES.map(s => s.check());

    // Run all checks in parallel
    const results = await Promise.all([...builtInChecks, ...customChecks]);

    // Filter by requested services if specified
    let services = results;
    if (options.services && options.services.length > 0) {
        services = results.filter(s =>
            options.services!.some(name =>
                s.name.toLowerCase().includes(name.toLowerCase())
            )
        );
    }

    // Calculate summary
    const summary = {
        healthy: services.filter(s => s.status === 'healthy').length,
        degraded: services.filter(s => s.status === 'degraded').length,
        unhealthy: services.filter(s => s.status === 'unhealthy').length,
        unknown: services.filter(s => s.status === 'unknown').length
    };

    // Determine overall status
    let overallStatus: ServiceStatus = 'healthy';
    if (summary.unhealthy > 0) {
        overallStatus = 'unhealthy';
    } else if (summary.degraded > 0) {
        overallStatus = 'degraded';
    } else if (summary.unknown === services.length) {
        overallStatus = 'unknown';
    }

    const duration = Date.now() - startTime;
    logInfo(SOURCE, `Health check completed in ${duration}ms. Status: ${overallStatus}`);

    return {
        timestamp: new Date(),
        overallStatus,
        services,
        summary
    };
}

/**
 * Quick check - only critical services
 */
export async function quickCheck(): Promise<{
    healthy: boolean;
    status: ServiceStatus;
    criticalServices: ServiceHealth[];
}> {
    const criticalServiceNames = ['Ollama', 'Node Process'];
    const report = await checkAllServices({
        services: criticalServiceNames,
        timeoutMs: 3000
    });

    return {
        healthy: report.overallStatus === 'healthy',
        status: report.overallStatus,
        criticalServices: report.services
    };
}

/**
 * Generate markdown report from health check results
 */
export function generateHealthReport(report: SystemHealthReport): string {
    const statusIcon = {
        healthy: '🟢',
        degraded: '🟡',
        unhealthy: '🔴',
        unknown: '⚪'
    };

    const lines: string[] = [
        '# System Health Report',
        '',
        `**Timestamp:** ${report.timestamp.toISOString()}`,
        `**Overall Status:** ${statusIcon[report.overallStatus]} ${report.overallStatus.toUpperCase()}`,
        '',
        '## Summary',
        '',
        `| Status | Count |`,
        `|--------|-------|`,
        `| Healthy | ${report.summary.healthy} |`,
        `| Degraded | ${report.summary.degraded} |`,
        `| Unhealthy | ${report.summary.unhealthy} |`,
        `| Unknown | ${report.summary.unknown} |`,
        '',
        '## Services',
        ''
    ];

    for (const service of report.services) {
        lines.push(`### ${statusIcon[service.status]} ${service.name}`);
        lines.push('');
        lines.push(`- **Status:** ${service.status}`);

        if (service.latencyMs !== undefined) {
            lines.push(`- **Latency:** ${service.latencyMs}ms`);
        }

        if (service.error) {
            lines.push(`- **Error:** ${service.error}`);
        }

        if (service.details) {
            lines.push(`- **Details:** \`${JSON.stringify(service.details)}\``);
        }

        lines.push('');
    }

    return lines.join('\n');
}

/**
 * Check a specific service by name
 */
export async function checkService(
    serviceName: string,
    timeoutMs: number = 5000
): Promise<ServiceHealth> {
    const name = serviceName.toLowerCase();

    switch (name) {
        case 'ollama':
            return checkOllama(timeoutMs);
        case 'python':
        case 'python api':
        case 'fastapi':
            return checkPythonAPI(timeoutMs);
        case 'mcp':
        case 'mcp server':
            return checkMCPServer(timeoutMs);
        case 'anythingllm':
            return checkAnythingLLM(timeoutMs);
        case 'dashboard':
        case 'ui':
            return checkDashboard(timeoutMs);
        case 'node':
        case 'node process':
            return checkNodeProcess();
        default: {
            // Check registered services
            const registered = SERVICES.find(s =>
                s.name.toLowerCase() === name
            );
            if (registered) {
                return registered.check();
            }
            return {
                name: serviceName,
                status: 'unknown',
                lastCheck: new Date(),
                error: 'Service not found'
            };
        }
    }
}

/**
 * Health check helpers: structured responses, retry, timeout config.
 */

import { Logger } from "./logger.js";

const healthLogger = new Logger("health.log");

export const HEALTH_CONFIG = {
  ollama: {
    timeoutMs: Number(process.env.HEALTH_OLLAMA_TIMEOUT_MS) || 5_000,
    retries: Number(process.env.HEALTH_OLLAMA_RETRIES) || 2,
    baseUrl: process.env.OLLAMA_BASE_URL || "http://127.0.0.1:11434",
  },
  anythingllm: {
    timeoutMs: Number(process.env.HEALTH_ANYTHINGLLM_TIMEOUT_MS) || 10_000,
    retries: Number(process.env.HEALTH_ANYTHINGLLM_RETRIES) || 1,
    baseUrl: process.env.ANYTHINGLLM_BASE_URL || "http://localhost:3001",
  },
  python: {
    timeoutMs: 8_000,
    retries: 1,
    baseUrl: process.env.PYTHON_API_URL || "http://127.0.0.1:8000",
  },
  cloudflare: {
    timeoutMs: 8_000,
    retries: 1,
  },
} as const;

export type ServiceStatus =
  | "healthy"
  | "unhealthy"
  | "no_agents"
  | "no_servers"
  | "error";

export interface HealthServiceResult {
  status: ServiceStatus;
  latencyMs?: number;
  error?: string;
}

export interface HealthResponse {
  status: "ok" | "degraded" | "error";
  timestamp: string;
  requestId?: string;
  services: {
    ollama: HealthServiceResult;
    anythingllm: HealthServiceResult;
    agents: HealthServiceResult;
    mcp: HealthServiceResult;
    python: HealthServiceResult;
    cloudflare: HealthServiceResult;
  };
}

async function fetchWithRetry(
  url: string,
  options: {
    timeout: number;
    method?: string;
    headers?: Record<string, string>;
  },
  retries: number,
): Promise<{ ok: boolean; latencyMs: number; status: number; error?: string }> {
  const start = Date.now();
  let lastErr: string | undefined;
  let lastStatus = 0;
  for (let i = 0; i <= retries; i++) {
    try {
      const res = await fetch(url, {
        method: options.method || "GET",
        signal: AbortSignal.timeout(options.timeout),
        headers: options.headers,
      });
      const latencyMs = Date.now() - start;
      lastStatus = res.status;
      if (res.ok) return { ok: true, latencyMs, status: res.status };
      lastErr = `HTTP ${res.status}`;
    } catch (e: any) {
      lastErr = e?.message ?? String(e);
    }
  }
  return {
    ok: false,
    latencyMs: Date.now() - start,
    status: lastStatus,
    error: lastErr,
  };
}

export async function checkOllamaHealth(): Promise<HealthServiceResult> {
  const { baseUrl, timeoutMs, retries } = HEALTH_CONFIG.ollama;
  const url = `${baseUrl}/api/tags`;
  const { ok, latencyMs, error } = await fetchWithRetry(
    url,
    { timeout: timeoutMs },
    retries,
  );
  await healthLogger.log("Ollama health", { ok, latencyMs, error });
  return {
    status: ok ? "healthy" : "unhealthy",
    latencyMs,
    error: ok ? undefined : error,
  };
}

export async function checkAnythingLLMHealth(): Promise<HealthServiceResult> {
  const apiKey = process.env.ANYTHINGLLM_API_KEY;
  if (!apiKey) {
    await healthLogger.log("AnythingLLM health skipped", {
      reason: "no API key",
    });
    return { status: "unhealthy", error: "API key not configured" };
  }
  const { baseUrl, timeoutMs, retries } = HEALTH_CONFIG.anythingllm;
  const url = `${baseUrl}/api/v1/workspaces`;
  const { ok, latencyMs, error } = await fetchWithRetry(
    url,
    { timeout: timeoutMs, headers: { Authorization: `Bearer ${apiKey}` } },
    retries,
  );
  await healthLogger.log("AnythingLLM health", {
    ok,
    latencyMs,
    error: error ? "present" : undefined,
  });
  return {
    status: ok ? "healthy" : "unhealthy",
    latencyMs,
    error: ok ? undefined : error,
  };
}

export async function checkPythonHealth(): Promise<HealthServiceResult> {
  const { baseUrl, timeoutMs, retries } = HEALTH_CONFIG.python;
  const url = `${baseUrl}/health`;
  const { ok, latencyMs, error } = await fetchWithRetry(
    url,
    { timeout: timeoutMs },
    retries,
  );
  await healthLogger.log("Python health", { ok, latencyMs, error });
  return {
    status: ok ? "healthy" : "unhealthy",
    latencyMs,
    error: ok ? undefined : error,
  };
}

export async function checkCloudflareHealth(): Promise<HealthServiceResult> {
  // Check Cloudflare Workers deployment (not AI Gateway directly)
  const workerUrl = process.env.CLOUDFLARE_WORKER_URL;

  if (!workerUrl) {
    return { status: "unhealthy", error: "Missing CLOUDFLARE_WORKER_URL" };
  }

  const { timeoutMs, retries } = HEALTH_CONFIG.cloudflare;

  // Ping the worker's health endpoint (if exists) or root
  const { ok, latencyMs, status, error } = await fetchWithRetry(
    workerUrl,
    { timeout: timeoutMs },
    retries,
  );

  // 200 OK or 404 (worker exists but no route) are both healthy
  const isHealthy = ok || status === 404;
  await healthLogger.log("Cloudflare health", {
    ok: isHealthy,
    latencyMs,
    status,
    error,
  });

  return {
    status: isHealthy ? "healthy" : "unhealthy",
    latencyMs,
    error: isHealthy ? undefined : error || `HTTP ${status}`,
  };
}

export function buildHealthResponse(
  ollama: HealthServiceResult,
  anythingllm: HealthServiceResult,
  python: HealthServiceResult,
  cloudflare: HealthServiceResult,
  agentsCount: number,
  mcpServersCount: number,
  requestId?: string,
): HealthResponse {
  const agents: HealthServiceResult = {
    status: agentsCount > 0 ? "healthy" : "no_agents",
