import fs from 'node:fs';
import path from 'node:path';

const TRACKS_DIR = path.resolve('conductor/tracks');

// Template for a generic meta.json
const createMetaTemplate = (dirName: string) => {
  const timestamp = new Date().toISOString();
  return {
    trackName: dirName,
    type: "Restored Track",
    priority: "MEDIUM",
    status: "active",
    progress: 0,
    goal: `Restored goal for ${dirName}. Please update with actual goal.`,
    assignee: "System",
    createdAt: timestamp,
    updatedAt: timestamp,
    context: "Automatically generated meta.json due to missing file.",
    phases: [
      {
        id: "phase1",
        name: "Phase 1: Restoration Assessment",
        status: "active",
        tasks: [
          "Task 1.1: Review project contents and update meta.json goal and context.",
          "Task 1.2: Identify current status and update progress."
        ]
      }
    ],
    acceptanceCriteria: [
      "meta.json is accurate reflecting the project state."
    ],
    nextStep: "Review and update meta.json"
  };
};

async function fixMissingMeta() {
  console.log(`Scanning ${TRACKS_DIR} for missing meta.json files...`);

  try {
    const entries = await fs.promises.readdir(TRACKS_DIR, { withFileTypes: true });

    // Filter for directories only
    const directories = entries.filter(entry => entry.isDirectory());

    let fixedCount = 0;
    let skippedCount = 0;

    for (const dir of directories) {
      const dirPath = path.join(TRACKS_DIR, dir.name);
      const metaPath = path.join(dirPath, 'meta.json');

      try {
        await fs.promises.access(metaPath);
        // console.log(`✅ ${dir.name}: meta.json exists.`);
        skippedCount++;
      } catch {
        console.log(`❌ ${dir.name}: meta.json MISSING. Generating default...`);

        const metaContent = createMetaTemplate(dir.name);
        await fs.promises.writeFile(metaPath, JSON.stringify(metaContent, null, 2), 'utf-8');
        console.log(`   ✨ Generated meta.json for ${dir.name}`);
        fixedCount++;
      }
    }

    console.log(`\nSummary:`);
    console.log(`- Total directories scanned: ${directories.length}`);
    console.log(`- Valid tracks (skipped): ${skippedCount}`);
    console.log(`- Fixed tracks (generated): ${fixedCount}`);

  } catch (error) {
    console.error("Error scanning tracks directory:", error);
  }
}

fixMissingMeta();

