                e.key === "Enter" && !e.shiftKey && (e.preventDefault(), send())
              }
              placeholder={
                mode === "orchestrator"
                  ? "Üzenet az Orchestratornak..."
                  : mode === "cloudflare_chat"
                    ? "Üzenet a Cloudflare Chat-nek..."
                    : mode === "cloudflare"
                      ? "Üzenet a Cloudflare Edge-nek..."
