}

Respond ONLY with the valid JSON object. No markdown blocks.
`;

      const responseText = await chatWithOllama(
        prompt,
        process.env.OLLAMA_MODEL || "gemma2:9b",
      );
      this.logger.info(`Raw Plan: ${responseText}`);

      // 2. Parse and Queue tasks
      try {
